-      sourceFolder, destinationFolder, nsresult::NS_ERROR_UNEXPECTED);
-  NS_ENSURE_SUCCESS(rv, rv);
-
-  return NS_OK;
+  return NotifyMessageCopyServiceComplete(sourceFolder, destinationFolder,
+                                          status);
 }

